INSERT INTO benefit_items_import VALUES
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 1, '意外事故失能', '意外事故失能保險金', '保額 × 附表比例', '第十六條意外事故失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，本公司按本附約保險單上所記載之保險金額為準，依附表二所列比例計算給付意外事故失能保險金。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 2, '航空交通意外事故失能', '航空交通意外事故失能保險金', '保額 × 3 × 附表比例', '第十七條航空交通意外事故失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的航空交通意外事故，自該航空交通意外事故發生之日起一百八十日以內致成附表二所列失能程度之一者，本公司除依第十六條約定給付意外事故失能保險金外，另按本附約保險單上所記載之保險金額的三倍為準，依附表二所列比例計算，再給付航空交通意外事故失能保險金。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 3, '每月生活補助', '每月生活補助保險金', NULL, '前項情形如被保險人自意外傷害事故發生之日起超過一百八十日致成附表二所列第一級至第六級失能程度之一者，受益人若能證明被保險人之失能與該意外傷害事故具有因果關係者，本公司仍依前項規定給付每月生活補助保險金，不受前項一百八十日之限制。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 4, '重大燒燙傷', '重大燒燙傷保險金', '保額 × 50%', '第二十二條重大燒燙傷保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，蒙受燒燙傷之傷害，經診斷符合第二條第十款所約定之重大燒燙傷者，本公司按診斷確定時本附約保險單上所記載之保險金額的百分之五十，給付重大燒燙傷保險金。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 5, '傷害醫療日額', '傷害醫療日額保險金', '日額 × 天數', '第二條傷害醫療日額保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院治療者，本公司按本附約保險單上所記載之「傷害醫療保險金日額」乘以實際住院日數給付「傷害醫療日額保險金」；'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 6, '燒燙傷、加護病房', '燒燙傷、加護病房保險金', '日額 × 2 × 天數', '第三條燒燙傷、加護病房保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，因此蒙受燒燙傷或其他意外傷害，於醫院燒燙傷或加護病房接受治療者，本公司將按本附約保險單上所記載之「傷害醫療保險金日額」的二倍乘以實際住進燒燙傷病房或加護病房之日數，給付「燒燙傷、加護病房保險金」。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 7, '出院療養', '出院療養保險金', NULL, '第四條出院療養保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，並於醫院住院後出院療養者，本公司按本附約保險單上所記載之「傷害醫療保險金日額」的二分之一乘以實際住院日數，給付「出院療養保險金」。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 8, '住院生活補助', '住院生活補助保險金', '日額 × 天數', '２.自第三十一日起，本公司按本附約保險單上所記載之「傷害醫療保險金日額」乘以實際超過三十日以上之住院日數，給付「住院生活補助保險金」。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 9, '傷害醫療', '傷害醫療限額保險金（實支實付）', '實支實付，每次以保單限額為限', '第二條傷害醫療限額保險金（實支實付）的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療者，本公司依其實際醫療費用，就超過全民健康保險給付部分，給付「傷害醫療限額保險金（實支實付）」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 1, '身故', '身故保險金', NULL, '第六條身故保險金的給付被保險人於本契約有效期間內遭受第三條約定的傷害事故，並於事故發生之日起一百八十日以內身故者，本公司按本契約保險單所記載的該被保險人的保險金額給付「身故保險金」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 2, '失能', '失能保險金', '保額 × 附表比例', '第七條失能保險金的給付被保險人於本契約有效期間內遭受第三條約定的傷害事故，並於事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按本契約保險單所記載該被保險人的保險金額為準，依該表所列比例給付「失能保險金」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 3, '傷害醫療', '傷害醫療保險金', '實支實付，每次以保單限額為限', '附件附加醫療保險金條款（傷害醫療保險金）第一條傷害醫療保險金的給付被保險人於本契約有效之保險期間內遭受本契約第三條的傷害事故，並於醫院或診所接受治療者，本公司以本契約保險單所記載的該被保險人的「每次傷害醫療保險金限額」為限，按每次事故實際醫療費用給付「傷害醫療保險金」。'),
  ('fubon', '富邦人壽 e心守護網路投保傷害保險', 1, '意外傷害失能生活扶助', '意外傷害失能生活扶助保險金', '保額 × 附表比例', '第十一條被保險人在本契約有效期間內遭受第二條約定的意外傷害事故，且自意外傷害事故發生之日起一百八十日以內致成附表一所列之第一級至第三級失能等級之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，每月按保險金額的1.5%乘以附表一所列比例計算所得之金額給付「意外傷害失能生活扶助保險金」，給付期限為60個月（不論被保險人生存與否）。'),
  ('fubon', '富邦人壽 e心守護網路投保傷害保險', 2, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '或前往不具有全民健康保險之醫院或診所治療者，致醫療費用未經全民健康保險給付，本公司依被保險人實際支付之醫療費用的75%給付「意外傷害醫療保險金」。'),
  ('fubon', '富邦人壽 e心守護網路投保傷害保險', 3, '意外傷害事故骨折', '意外傷害事故骨折保險金', NULL, '第十三條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療，診斷確定致成骨折別表所列項目之一，本公司依附表三骨折別表所載意外傷害事故骨折保險金限額乘上所定給付比例計算，給付「意外傷害事故骨折保險金」。'),
  ('fubon', '富邦人壽 e心守護網路投保傷害保險', 4, '重大燒燙傷', '重大燒燙傷保險金', '保額 × 25%', '第十四條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，致其身體燒燙傷面積達全身百分之二十以上或顏面燒燙傷合併五官功能障礙(範圍列於附表四)，經醫院醫師診斷確定並治療，且自意外傷害事故發生之日起屆滿十五日仍生存者，本公司按致成重大燒燙傷當時保險金額的25%給付「重大燒燙傷保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 1, '意外身故', '一般意外傷害身故保險金', '保額 × 1', '第八條本附約各項「意外傷害身故保險金」約定如下：一、「一般意外傷害身故保險金」：被保險人於本附約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起ADG11401013/14商品代號：ADG一百八十日以內身故者，本公司按保險金額給付「一般意外傷害身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 2, '大眾運輸交通工具意外傷害身故', '大眾運輸交通工具意外傷害身故保險金', '保額 × 2', '二、「大眾運輸交通工具意外傷害身故保險金」：被保險人於本附約有效期間內，因搭乘第二條約定的大眾運輸交通工具而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按保險金額二倍給付「大眾運輸交通工具意外傷害身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 3, '公共建築物火災意外傷害身故', '公共建築物火災意外傷害身故保險金', '保額 × 1', '三、「公共建築物火災意外傷害身故保險金」：被保險人於本附約有效期間內，因第二條約定的公共建築物火災而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按保險金額給付「公共建築物火災意外傷害身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 4, '電梯意外傷害身故', '電梯意外傷害身故保險金', '保額 × 1', '四、「電梯意外傷害身故保險金」：被保險人於本附約有效期間內，因乘坐第二條約定的電梯而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按保險金額給付「電梯意外傷害身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 5, '一氧化碳中毒意外傷害身故', '一氧化碳中毒意外傷害身故保險金', '保額 × 1', '五、「一氧化碳中毒意外傷害身故保險金」：被保險人於本附約有效期間內，因遭受一氧化碳中毒意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按保險金額給付「一氧化碳中毒意外傷害身故保險金」後，本附約效力即行終止。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 6, '意外失能', '一般意外傷害失能保險金', '保額 × 附表比例', '第九條本附約各項「意外傷害失能保險金」約定如下：一、「一般意外傷害失能保險金」：被保險人於本附約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，按保險金額乘以附表一所列給付比例計算所得之金額給付「一般意外傷害失能保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 7, '大眾運輸交通工具意外傷害失能', '大眾運輸交通工具意外傷害失能保險金', '保額 × 2 × 附表比例', '意外傷害失能保險金」：被保險人於本附約有效期間內，因搭乘第二條約定的大眾運輸交通工具而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，除依第一款約定給付「一般意外傷害失能保險金」外，另按保險金額二倍乘以附表一所列給付比例計算所得之金額給付「大眾運輸交通工具意外傷害失能保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 8, '公共建築物火災意外傷害失能', '公共建築物火災意外傷害失能保險金', '保額 × 附表比例', '建築物火災意外傷害失能保險金」：被保險人於本附約有效期間內，因第二條約定的公共建築物火災而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，除依第一款約定給付「一般意外傷害失能保險金」外，另按保險金額乘以附表一所列給付比例計算所得之金額給付「公共建築物火災意外傷害失能保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 9, '電梯意外傷害失能', '電梯意外傷害失能保險金', '保額 × 附表比例', '人於本附約有效期間內，因乘坐第二條約定的電梯而遭受意外傷害事故，自意外傷害事故ADG11401014/14商品代號：ADG發生之日起一百八十日以內致成附表一所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，除依第一款約定給付「一般意外傷害失能保險金」外，另按保險金額乘以附表一所列給付比例計算所得之金額給付「電梯意外傷害失能保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 10, '一氧化碳中毒意外傷害失能', '一氧化碳中毒意外傷害失能保險金', '保額 × 附表比例', '五、「一氧化碳中毒意外傷害失能保險金」：被保險人於本附約有效期間內，因遭受一氧化碳中毒意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，除依第一款約定給付「一般意外傷害失能保險金」外，另按保險金額乘以附表一所列給付比例計算所得之金額給付「一氧化碳中毒意外傷害失能保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害暨兒童傷害失能保險附約', 11, '重大燒燙傷', '重大燒燙傷保險金', '保額 × 40%', '第十一條被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，致其身體蒙受二度燒燙傷面積大於全身面積百分之二十、三度燒燙傷面積大於全身面積百分之十或顏面燒燙傷合併五官功能障礙（範圍列於附表二），經醫院診斷確定並住院或門診治療者，本公司按保險金額的百分之四十給付「重大燒燙傷保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 1, '意外身故', '一般意外傷害身故保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '第十條本契約各項「意外傷害身故保險金」約定如下：一、「一般意外傷害身故保險金」：被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按致成身故當時之投保計劃別依附表一約定之金額給付「一般意外傷害身故保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 2, '大眾運輸交通工具意外傷害身故', '大眾運輸交通工具意外傷害身故保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '二、「大眾運輸交通工具意外傷害身故保險金」：被保險人於本契約有效期間內，因搭乘第二條約定的大眾運輸交通工具而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按致成身故當時之投保計劃別依附表一約定之金額給付「大眾運輸交通工具意外傷害身故保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 3, '搭乘機車或汽車意外傷害身故', '搭乘機車或汽車意外傷害身故保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '車意外傷害身故保險金」：NAG1_311510014/17商品代號：NAG1/NAG2/NAG3被保險人於本契約有效期間內，因搭乘機車或汽車遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按致成身故當時之投保計劃別依附表一約定之金額給付「搭乘機車或汽車意外傷害身故保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 4, '海外意外傷害身故', '海外意外傷害身故保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '四、「海外意外傷害身故保險金」：被保險人於本契約有效期間且於海外停留保障期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按致成身故當時之投保計劃別依附表一約定之金額給付「海外意外傷害身故保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 5, '假日意外傷害身故', '假日意外傷害身故保險金', '計劃1 100萬｜計劃2 150萬｜計劃3 200萬', '五、「假日意外傷害身故保險金」:被保險人於本契約有效期間內，於假日遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依本項第一款約定給付「一般意外傷害身故保險金」外，另按致成身故當時之投保計劃別依附表一約定之金額給付「假日意外傷害身故保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 6, '意外失能', '一般意外傷害失能保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '一條本契約各項「意外傷害失能保險金」約定如下：一、「一般意外傷害失能保險金」：被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，經醫院醫師診斷確定，本公司按失能診斷確定日當時之投保計劃別依附表一約定之金額，乘上附表二所列之給付比例計算所得金額給付「一般意外傷害失能保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 7, '大眾運輸交通工具意外傷害失能', '大眾運輸交通工具意外傷害失能保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '：被保險人於本契約有效期間內，因搭乘第二條約定的大眾運輸交通工具而遭受意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，經醫院醫師診斷確定，本公司除依本項第一款約定給付「一般意外傷害失能保險金」外，另按失能診斷確定日當時之投保計劃別依附表一約定之金額，乘上附表二所列之給付比例計算所得金額給付「大眾運輸交通工具意外傷害失能保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 8, '搭乘機車或汽車意外傷害失能', '搭乘機車或汽車意外傷害失能保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '保險金」：被保險人於本契約有效期間內，因搭乘機車或汽車遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，經醫院醫師診斷確定，本公司除依本項第一款約定給付「一般意外傷害失能保險金」外，另按失能診斷確定日當時之投保計劃別依附表一約定之金額，乘上附表二所列之給付比例計算所得金額給付「搭乘機車或汽車意外傷害失能保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 9, '海外意外傷害失能', '海外意外傷害失能保險金', '計劃1 200萬｜計劃2 300萬｜計劃3 400萬', '」：被保險人於本契約有效期間且於海外停留保障期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，經醫院醫師診斷確定，本公司除依本項第一款約定給付「一般意外傷害失能保險金」外，另按失能診斷確定日當時之投保計劃別依附表一約定之金額，乘上附表二所列之給付比例計算所得金額給付「海外意外傷害失能保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 10, '假日意外傷害失能', '假日意外傷害失能保險金', '計劃1 100萬｜計劃2 150萬｜計劃3 200萬', '外傷害失能保險金」：被保險人於本契約有效期間內，於假日遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，經醫院醫師診斷確定，本公司除依本項第一款約定給付「一般意外傷害失能保險金」外，另按失能診斷確定日當時之投保計劃別依附表一約定之金額，乘上附表二所列之給付比例計算所得金額給付「假日意外傷害失能保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 11, '意外傷害失能生活補助', '意外傷害失能生活補助保險金', '計劃1 100萬｜計劃2 200萬｜計劃3 200萬', '第十三條被保險人在本契約有效期間內，因遭受第二條約定的意外傷害事故，且自意外傷害事故發生之日起一百八十日以內，致成附表二所列之第一級至第三級失能等級之一者，經醫院醫師診斷確定，本公司按失能診斷確定日之投保計劃別依附表一約定之金額給付「意外傷害失能生活補助保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 12, '嚴重第三度燒燙傷', '嚴重第三度燒燙傷保險金', '200萬', '第十四條被保險人於本契約有效期間內，經醫院醫師診斷確定遭受第二條約定的嚴重第三度燒燙傷者，本公司按診斷確定當時之投保計劃別依附表一約定之金額給付「嚴重第三度燒燙傷保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 13, '食物中毒', '食物中毒保險金', '計劃1 2,000元/次｜計劃2 3,000元/次｜計劃3 3,000元/次', '第十五條被保險人於本契約有效期間內，因發生第二條約定的食物中毒，經醫院醫師診斷必須住院治療且已實際接受住院治療者，本公司按診斷確定當時之投保計劃別依附表一約定之金額給付「食物中毒保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 14, '嚴重頭部創傷', '嚴重頭部創傷保險金', '計劃1 75萬｜計劃2 100萬｜計劃3 100萬', '第十六條被保險人於本契約有效期間內，經醫院醫師診斷確定罹患第二條約定之嚴重頭部創傷者，本公司按診斷確定當時之投保計劃別依附表一約定之金額給付「嚴重頭部創傷保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 15, '意外傷害住院醫療', '意外傷害住院醫療保險金', '計劃1 1,000/日｜計劃2 2,000/日｜計劃3 2,000/日', '人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院接受住院治療者，本公司按致成意外傷害事故當時之投保計劃別依附表一約定之每日給付金額，乘以被保險人該次實際住院日數（含入、出病房當日）計算所得之金額NAG1_311510016/17商品代號：NAG1/NAG2/NAG3給付「意外傷害住院醫療保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 16, '意外傷害加護病房住院醫療', '意外傷害加護病房住院醫療保險金', '計劃1 1,000/日｜計劃2 2,000/日｜計劃3 2,000/日', '本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院之加護病房接受住院治療者，本公司除依本項第一款約定給付「意外傷害住院醫療保險金」外，另按致成意外傷害事故當時之投保計劃別依附表一約定之每日給付金額，乘以被保險人該次實際入住加護病房日數（含入、出加護病房當日）計算所得之金額給付「意外傷害加護病房住院醫療保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 17, '意外傷害住院看護', '意外傷害住院看護保險金', '計劃1 500/日｜計劃2 1,000/日｜計劃3 1,000/日', '護保險金」：被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院接受住院治療者，本公司除依本項第一款約定給付「意外傷害住院醫療保險金」外，另按致成意外傷害事故當時之投保計劃別依附表一約定之每日給付金額，乘以被保險人該次實際住院日數（含入、出病房當日）計算所得之金額給付「意外傷害住院看護保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 18, '意外傷害燒燙傷中心住院醫療', '意外傷害燒燙傷中心住院醫療保險金', '計劃1 1,000/日｜計劃2 2,000/日｜計劃3 2,000/日', 'G1_311510017/17商品代號：NAG1/NAG2/NAG3一百八十日以內，而於醫院之燒燙傷中心接受住院治療者，本公司除依本項第一款約定給付「意外傷害住院醫療保險金」外，另按致成意外傷害事故當時之投保計劃別依附表一約定之每日給付金額，乘以被保險人該次實際入住燒燙傷中心日數（含入、出燒燙傷中心當日）計算所得之金額給付「意外傷害燒燙傷中心住院醫療保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 19, '意外傷害住院手術醫療', '意外傷害住院手術醫療保險金', '計劃1 2,500/次｜計劃2 5,000/次｜計劃3 5,000/次', '五、「意外傷害住院手術醫療保險金」：被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院住院接受手術治療且已施行手術者，本公司除依本項第一款約定給付「意外傷害住院醫療保險金」外，另按致成意外傷害事故當時之投保計劃別依附表一約定之金額給付「意外傷害住院手術醫療保險金」。'),
  ('fubon', '富邦人壽意外無憂傷害保險', 20, '意外傷害住院生活補助', '意外傷害住院生活補助保險金', '3日(含)以上 5,000/次；8日(含)以上 3,000/次；15日(含)以上 2,000/次', '活補助保險金」：被保險人於本契約有效期間內，因遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院接受住院治療者，本公司除依本項第一款約定給付「意外傷害住院醫療保險金」外，另按致成意外傷害事故當時之投保計劃別依附表一約定之金額，按照被保險人該次實際住院日數（含入、出病房當日）所達到之標準，累加給付「意外傷害住院生活補助保險金」。'),
  ('cathay', '國泰人壽微型個人傷害醫療保險附約', 1, '傷害醫療', '傷害醫療保險金', '實支實付，每次以保單限額為限', '第十二條傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療者，本公司依其實際醫療費用，就超過全民健康保險給付部分，給付「傷害醫療保險金」。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 1, '傷害醫療', '傷害醫療保險金', '實支實付（每單位 30,000 元）或日額（每單位 1,000 元）擇一', '一條傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經醫院或診所治療者，被保險人得於下列二款保險金給付方式中，自行選擇一款較有利者向本公司申請給付：一、實支實付：以每一投保單位三萬元乘以約定投保單位數後之「每次傷害醫療保險金限額」為限，依其實際醫療費用給付傷害醫療保險金。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 2, '加護病房', '加護病房保險金', NULL, '第十二條加護病房保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，於醫院加護病房接受治療者，本公司將先按每一投保單位三仟元乘以約定投保單位數後計得之金額，再乘以實際住進加護病房之日數給付加護病房保險金。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 3, '燒燙傷病房', '燒燙傷病房保險金', NULL, '第十三條燒燙傷病房保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故蒙受燒燙傷之傷害，於醫院燒燙傷病房接受治療者，本公司將先按每一投保單位三仟元乘以約定投保單位數後計得之金額，再乘以實際住進燒燙傷病房之日數給付燒燙傷病房保險金。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 4, '燒燙傷回診', '燒燙傷回診保險金', NULL, '第十四條燒燙傷回診保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故蒙受燒燙傷之傷害，經醫院住院治療後出院者，於出院後一年內因前次燒燙傷之原因至醫院或診所接受門診或復健治療時，本公司將先按每一投保單位一仟元乘以約定投保單位數後計得之金額，再乘以實際門診或復健次數給付燒燙傷回診保險金，但每日門診或復健逾一次以上者，僅以一次計算。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 5, '重大燒燙傷', '重大燒燙傷保險金', NULL, '第十五條重大燒燙傷保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，蒙受燒燙傷之傷害，經診斷符合第二條所約定之重大燒燙傷者，本公司按診斷確定時每一投保單位三十萬元乘以約定投保單位數後計得之金額，給付重大燒燙傷保險金。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 6, '意外骨折', '意外骨折保險金', NULL, '第十六條意外骨折保險金的給付被保險人於本附約有效期間內遭受條款第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院、診所(不含國術館、接骨所)診斷致成附表二骨折別表所列骨折項目之一者，本公司按骨折別表所定給付金額乘以約定投保單位數後，給付意外骨折保險金。'),
  ('cathay', '國泰人壽超愛寶貝一年定期傷害醫療保險附約(無身故給付)', 7, '意外脫臼手術', '意外脫臼手術保險金', NULL, '第十七條意外脫臼手術保險金的給付被保險人於本附約有效期間內遭受條款第二條約定的意外傷害事故致成附表三脫臼別表所列脫臼項目之一，自意外傷害事故發生之日起一百八十日以內經醫師診斷必須且實際施行「脫臼開放性復位術」治療者，本公司按脫臼別表所定給付金額乘以約定投保單位數後，給付意外脫臼手術保險金。'),
  ('cathay', '國泰人壽自由配一年定期意外住院日額傷害保險附約', 1, '傷害醫療日額', '傷害醫療日額保險金', '日額 × 天數', '第十條傷害醫療日額保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院治療者，本公司按「傷害醫療保險金日額」乘以實際住院日數給付「傷害醫療日額保險金」；'),
  ('cathay', '國泰人壽享保障微型個人傷害醫療保險附約', 1, '傷害醫療', '傷害醫療保險金', '實支實付，每次以保單限額為限', '第十一條傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療者，本公司依其實際醫療費用，就超過全民健康保險給付部分，給付「傷害醫療保險金」。'),
  ('fubon', '富邦人壽網投微型意外傷害醫療保險附約', 1, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '或前往不具有全民健康保險之醫院或診所治療者，致醫療費用未經全民健康保險給付，本公司依被保險人實際支付之醫療費用的百分之七十五給付「意外傷害醫療保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害醫療保險給付附加條款', 1, '意外傷害脫臼開放性復位術', '意外傷害脫臼開放性復位術保險金', NULL, '第四條被保險人於本附加條款有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經醫院或診所治療，診斷確定致成附表一脫臼別表所列脫臼項目之一，經醫師診斷必須且實際施行「脫臼開放性復位術」治療者，本公司按致成意外傷害事故當時之附表一所列之金額，乘上給付比例計算所得金額給付「意外傷害脫臼開放性復位術保險金」。'),
  ('fubon', '富邦人壽享安寶意外傷害醫療保險給付附加條款', 2, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '本附加條款有效期間內，被保險人於海外遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經當地登記合格的醫院或診所治療者，本公司依第一項約定給付「意外傷害醫療保險金」，但同一次傷害最高給付治療日數為十四天，且給付總額不得超過「保險金額」。'),
  ('fubon', '富邦人壽安鑫護意外傷害住院醫療保險附約', 1, '意外傷害住院醫療', '意外傷害住院醫療保險金', '日額 × 天數', '第八條被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，而於醫院接受住院治療者，本公司按「傷害醫療保險金日額」乘以被保險人實際住院日數（含出院及入院當日），給付「意外傷害住院醫療保險金」。'),
  ('fubon', '富邦人壽安鑫護意外傷害住院醫療保險附約', 2, '意外傷害門診手術醫療', '意外傷害門診手術醫療保險金', '日額 × 1', '第九條被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經醫師診斷必須於醫院或診所以門診方式接受手術治療且已接受該手術者，本公司按「傷害醫療保險金日額」給付「意外傷害門診手術醫療保險金」。'),
  ('nanshan', '南山人壽Full樂微型傷害醫療保險附約', 1, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '第七條意外傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日內，經登記合格的醫院或診所治療者，本公司就其實際醫療費用，超過全民健康保險給付部分，給付「意外傷害醫療保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 1, '意外身故', '意外身故保險金', '每次 2,000,000 元', '第八條意外身故保險金或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內死亡者，本公司按新臺幣二百萬元給付「意外身故保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 2, '意外失能', '意外失能保險金', NULL, '被保險人因本次意外傷害事故所致之失能，如合併以前(含本附約訂立前)的失能，可領附表一所列較嚴重項目的「意外失能保險金」者，本公司按較嚴重的項目給付「意外失能保險金」，但以前的失能，視同已給付「意外失能保險金」，應扣除之。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 3, '意外重大燒燙傷', '意外重大燒燙傷保險金', '每次 500,000 元', '第十條意外重大燒燙傷保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成身體蒙受二度燒燙傷面積大於全身20％、三度燒燙傷面積大於全身10％或顏面燒燙傷合併五官功能障礙者(上述燒燙傷統稱為重大燒燙傷，其範圍依國際疾病分類標準，詳見附表二)，本公司按新臺幣五十萬元給付「意外重大燒燙傷保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 4, '意外一至六級傷害失能補償', '意外一至六級傷害失能補償保險金', NULL, '第十一條意外一至六級傷害失能補償保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列第一級至第六級失能程度之一，且至診斷確定失能之日仍生存者，本公司按照第九條給付之「意外失能保險金」的百分之一給付「意外一至六級傷害失能補償保險金」，並於以後每月以前開診斷確定失能日之相當日(無相當日者為該月之末日)，按月給付「意外一至六級傷害失能補償保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 5, '航空意外身故', '航空意外身故保險金', '每次 2,000,000 元', '第十二條航空意外身故保險金或喪葬費用保險金的給付被保險人於本附約有效期間內遭受航空意外傷害事故，自航空意外傷害事故發生之日起一百八十日以內死亡者，本公司除依第八條約定辦理外，另按新臺幣二百萬元給付「航空意外身故保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 6, '航空意外失能', '航空意外失能保險金', NULL, '被保險人因本次航空意外傷害事故所致之失能，如合併以前(含本附約訂立前)的失能，可領附表一所列較嚴重項目的「航空意外失能保險金」者，本公司按較嚴重的項目給付「航空意外失能保險金」，但以前的失能，視同已給付「航空意外失能保險金」，應扣除之。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 7, '水陸大眾運輸意外身故', '水陸大眾運輸意外身故保險金', '每次 2,000,000 元', '第十四條水陸大眾運輸意外身故保險金或喪葬費用保險金的給付被保險人於本附約有效期間內遭受水陸大眾運輸意外傷害事故，自水陸大眾運輸意外傷害事故發生之日起一百八十日以內死亡者，本公司除依第八條約定辦理外，另按新臺幣二百萬元給付「水陸大眾運輸意外身故保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 8, '水陸大眾運輸意外失能', '水陸大眾運輸意外失能保險金', NULL, '被保險人因本次水陸大眾運輸意外傷害事故所致之失能，如合併以前(含本附約訂立前)的失能，可領附表一所列較嚴重項目的「水陸大眾運輸意外失能保險金」者，本公司按較嚴重的項目給付「水陸大眾運輸意外失能保險金」，但以前的失能，視同已給付「水陸大眾運輸意外失能保險金」，應扣除之。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 9, '天然災害意外身故', '天然災害意外身故保險金', '每次 2,000,000 元', '第十六條天然災害意外身故保險金或喪葬費用保險金的給付被保險人於本附約有效期間內遭受天然災害意外傷害事故，自天然災害意外傷害事故發生之日起一百八十日以內死亡者，本公司除依第八條約定辦理外，另按新臺幣二百萬元給付「天然災害意外身故保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 10, '天然災害意外失能', '天然災害意外失能保險金', NULL, '被保險人因本次天然災害意外傷害事故所致之失能，如合併以前(含本附約訂立前)的失能，可領附表一所列較嚴重項目的「天然災害意外失能保險金」者，本公司按較嚴重的項目給付「天然災害意外失能保險金」，但以前的失能，視同已給付「天然災害意外失能保險金」，應扣除之。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 11, '特定交通事故重大創傷', '特定交通事故重大創傷保險金', '每次 200,000 元', '第十八條特定交通事故重大創傷保險金的給付被保險人於本附約有效期間內遭受第二條約定的交通事故，自交通事故發生之日起一百八十日以內，經醫院醫師診斷，其傷害程度符合附表三所列重大創傷程度之一且於醫院接受住院治療日數連續達五日(含)以上且仍生存者，本公司按新臺幣二十萬元給付「特定交通事故重大創傷保險金」。'),
  ('nanshan', '南山人壽成意實足意外傷害醫療保險附約', 12, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '第十九條意外傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療者，本公司就其實際醫療費用給付「意外傷害醫療保險金」。'),
  ('nanshan', '南山人壽意外骨折暨傷害醫療保險附約', 1, '傷害醫療', '意外傷害醫療保險金', '實支實付，每次以保單限額為限', '第九條意外傷害醫療保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院或診所治療者，本公司就其實際醫療費用給付「意外傷害醫療保險金」。'),
  ('nanshan', '南山人壽意外骨折暨傷害醫療保險附約', 2, '意外骨折', '意外骨折保險金', NULL, '第十一條意外骨折保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日內致成「骨折給付金額表」所列骨折項目之一，並經合法成立之醫院、診所診斷者，如其骨折為開放性骨折，本公司按「骨折給付金額表」所列骨折項目對應之給付金額給付「意外骨折保險金」，如係閉鎖性骨折並施行見血復位術，則按開放性骨折給付金額之百分之七十五給付，如係閉鎖性骨折但未施行見血復位術，則按開放性骨折給付金額之百分之二十五給付。'),
  ('nanshan', '南山人壽意外骨折暨傷害醫療保險附約', 3, '意外內臟或腦損傷手術', '意外內臟或腦損傷手術保險金', '每次 150,000 元', '第十二條意外內臟或腦損傷手術保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成下列情形之一者，本公司按新臺幣十五萬元給付「意外內臟或腦損傷手術保險金」。'),
  ('nanshan', '南山人壽意外骨折暨傷害醫療保險附約', 4, '意外脫臼切開手術', '意外脫臼切開手術保險金', NULL, '第十三條意外脫臼切開手術保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故致成「脫臼給付金額表」所列脫臼項目之一，自意外傷害事故發生之日起一百八十日以內經醫師診斷必須且實際施行切開術治療者，本公司按「脫臼給付金額表」所列脫臼項目對應之給付金額給付「意外脫臼切開手術保險金」。'),
  ('nanshan', '南山人壽意外傷害醫療日額給付附加條款', 1, '傷害醫療', '附加條款（樣本）意外傷害醫療保險金', '日額 × 天數', '/IDHI南山人壽保險股份有限公司（以下簡稱「本公司」）南山人壽意外傷害醫療日額給付附加條款（樣本）意外傷害醫療保險金日額一、本商品經本公司合格簽署人員檢視其內容業已符合一般精算原則及保險法令，惟為確保權益，基於保險公司與消費者衡平對等原則，消費者仍應詳加閱讀保險單條款與相關文'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 1, '意外身故', '意外身故保險金', '保額 × 1', '第七條意外身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內死亡者，本公司按保險金額給付「意外身故保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 2, '意外第一級失能', '意外第一級失能保險金', '保額 × 1', '第八條意外第一級失能保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列第一級失能程度之一者，本公司按保險金額給付「意外第一級失能保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 3, '意外骨折', '意外骨折保險金', NULL, '第九條意外骨折保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日內致成「骨折給付表」所列骨折項目之一，並經合法成立之醫院、診所診斷者，如其骨折為開放性骨折，本公司按保險金額乘以「骨折給付表」所列骨折項目對應之百分比給付「意外骨折保險金」，如係閉鎖性骨折並施行見血復位術，則按開放性骨折給付金額之百分之七十五給付，如係閉鎖性骨折但未施行見血復位術，則按開放性骨折給付金額之百分之二十五給付。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 4, '意外內臟或腦損傷手術', '意外內臟或腦損傷手術保險金', '保額 × 25%', '第十條意外內臟或腦損傷手術保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成下列情形之一者，本公司按保險金額的百分之二十五給付「意外內臟或腦損傷手術保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 5, '意外脫臼切開手術', '意外脫臼切開手術保險金', NULL, '第十一條意外脫臼切開手術保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故致成「脫臼給付表」所列脫臼項目之一，自意外傷害事故發生之日起一百八十日以內經醫師診斷必須且實際施行切開術治療者，本公司按保險金額乘以「脫臼給付表」所列脫臼項目對應之百分比給付「意外脫臼切開手術保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險', 6, '特定交通事故重大創傷', '特定交通事故重大創傷保險金', '保額 × 30%', '第十二條特定交通事故重大創傷保險金的給付被保險人於本契約有效期間內遭受第二條約定的交通事故，自交通事故發生之日起一百八十日以內，經醫院醫師診斷，其傷害程度符合附表三所列重大創傷程度之一且於醫院接受住院治療日數連續達五日(含)以上且仍生存者，本公司按保險金額的百分之三十給付「特定交通事故重大創傷保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險附約', 1, '意外第一級失能', '意外第一級失能保險金', '保額 × 1', '第九條意外第一級失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列第一級失能程度之一者，本公司按保險金額給付「意外第一級失能保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險附約', 2, '意外骨折', '意外骨折保險金', NULL, '第十條意外骨折保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日內致成「骨折給付表」所列骨折項目之一，並經合法成立之醫院、診所診斷者，如其骨折為開放性骨折，本公司按保險金額乘以「骨折給付表」所列骨折項目對應之百分比給付「意外骨折保險金」，如係閉鎖性骨折並施行見血復位術，則按開放性骨折給付金額之百分之七十五給付，如係閉鎖性骨折但未施行見血復位術，則按開放性骨折給付金額之百分之二十五給付。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險附約', 3, '意外內臟或腦損傷手術', '意外內臟或腦損傷手術保險金', '保額 × 25%', '第十一條意外內臟或腦損傷手術保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成下列情形之一者，本公司按保險金額的百分之二十五給付「意外內臟或腦損傷手術保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險附約', 4, '意外脫臼切開手術', '意外脫臼切開手術保險金', NULL, '第十二條意外脫臼切開手術保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故致成「脫臼給付表」所列脫臼項目之一，自意外傷害事故發生之日起一百八十日以內經醫師診斷必須且實際施行切開術治療者，本公司按保險金額乘以「脫臼給付表」所列脫臼項目對應之百分比給付「意外脫臼切開手術保險金」。'),
  ('nanshan', '南山人壽意外骨折及特定手術傷害醫療保險附約', 5, '特定交通事故重大創傷', '特定交通事故重大創傷保險金', '保額 × 30%', '第十三條特定交通事故重大創傷保險金的給付被保險人於本附約有效期間內遭受第二條約定的交通事故，自交通事故發生之日起一百八十日以內，經醫院醫師診斷，其傷害程度符合附表三所列重大創傷程度之一且於醫院接受住院治療日數連續達五日(含)以上且仍生存者，本公司按保險金額的百分之三十給付「特定交通事故重大創傷保險金」。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 1, '健康管理回饋', '健康管理回饋保險金', NULL, '第十條被保險人於本契約有效之繳費期間內，紀錄該保單年度指定期間內之有效健康公里數，並於該保單年度指定期間內將有效健康公里數上傳本公司資料庫，如達到下列各款標準之一，且於該保單年度屆滿時本契約有效而被保險人仍生存者，本公司將按其達到標準之最高等級，以mo幣給付健康管理回饋保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 2, '意外傷害骨折', '意外傷害骨折保險金', '保額 × 附表比例', '第十一條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經醫院或診所治療，診斷確定致成附表二骨折別表所列項目之一，本公司按保險金額乘以附表二骨折別表所定給付比例，給付意外傷害骨折保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 3, '意外傷害脫臼開放性復位術', '意外傷害脫臼開放性復位術保險金', '保額 × 附表比例', '第十二條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經醫院或診所治療，診斷確定致成附表三脫臼別表所列脫臼項目之一，經醫師診斷必須且實際施行「脫臼開放性復位術」治療者，本公司依其脫臼部位按保險金額乘以附表三脫臼別表所定給付比例，給付意外傷害脫臼開放性復位術保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 4, '意外傷害創傷縫合處置', '意外傷害創傷縫合處置保險金', '保額 × 附表比例', '第十三條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，於醫院或診所經醫師診斷必須接受創傷縫合處置治療且已接受縫合處置者，本公司依其創傷大小按保險金額的1％乘以附表四意外創傷縫合處置項目及給付比例表所定給付比例，給付意外傷害創傷縫合處置保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 5, '意外傷害跟腱斷裂重建或縫合術', '意外傷害跟腱斷裂重建或縫合術保險金', '保額 × 10%', '第十四條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，於醫院或診所經醫師診斷必須接受「跟腱斷裂重建術」或「跟腱斷裂縫合術」治療且已實際接受該手術者，本公司按保險金額之10％給付意外傷害跟腱斷裂重建或縫合術保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 6, '意外傷害十字韌帶重建或修補術', '意外傷害十字韌帶重建或修補術保險金', '保額 × 10%', '第十五條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，於醫院或診所經醫師診斷必須接受「十字韌帶重建術」或「十字韌帶修補術」治療且已實際接受該手術者，本公司按保險金額之10％給付意外傷害十字韌帶重建或修補術保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 7, '意外身故', '意外傷害身故保險金', '保額 × 1', '第十六條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按保險金額給付意外傷害身故保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 8, '身故', '喪葬費用保險金', NULL, '前項情形，如要保人向二家（含）以上保險公司投保，或向同一保險公司投保數個保險契（附）約，且其投保之喪葬費用保險金額合計超過所定之限額者，本公司於所承保之喪葬費用金額範圍內，依各要保書所載之要保時間先後，依約給付喪葬費用保險金至前項喪葬費用額度上限為止，如有二家以上保險公司之保險契約要保時間相同或無法區分其要保時間之先後者，各該保險公司應依其喪葬費用保險金額與扣除要保時間在先之保險公'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 9, '特定事故意外傷害身故', '特定事故意外傷害身故保險金', '保額 × 1', '第十七條被保險人於本契約有效期間內遭受第二條約定的特定事故，自特定事故發生之日起一百八十日以內身故者，本公司除依第十六條約定給付意外傷害身故保險金或喪葬費用保險金外，另按保險金額給付特定事故意外傷害身故保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 10, '比例給付意外傷害失能', '比例給付意外傷害失能保險金', NULL, '第十八條被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表五所列失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，按保險金額乘以附表五所列給付比例給付意外傷害失能保險金。'),
  ('fubon', '富邦人壽溢起馬拉松傷害保險', 11, '意外失能', '意外傷害失能保險金', NULL, '被保險人因本次意外傷害事故所致之失能，如合併以前（含本契約訂立前）的失能，可領附表五所列較嚴重項目的意外傷害失能保險金者，本公司按較嚴重的項目給付意外傷害失能保險金，但以前的失能，視同已給付意外傷害失能保險金，應扣除之。'),
  ('cathay', '國泰人壽新意外傷害事故骨折保險金附加條款', 1, '意外傷害事故骨折', '意外傷害事故骨折保險金', '保額 × 附表比例', '主要給付項目：給付項目給付金額意外傷害事故骨折保險金保險金額╳骨折別表所定給付比例※'),
  ('cathay', '國泰人壽新意外傷害重大燒燙傷保險金附加條款', 1, '意外傷害重大燒燙傷', '意外傷害重大燒燙傷保險金', '保額 × 1', '第三條意外傷害重大燒燙傷保險金的給付被保險人於本附加條款有效期間內遭受本契約條款第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經具備治療燒燙傷設備的醫院住院治療，符合本附加條款第二條所約定之「重大燒燙傷」者，本公司按本契約保險單上所記載之保險金額給付「意外傷害重大燒燙傷保險金」。'),
  ('cathay', '國泰人壽新行人或大眾交通工具意外傷害事故保險金附加條款', 1, '行人或大眾交通工具意外傷害事故身故', '行人或大眾交通工具意外傷害事故身故保險金', '保額 × 1', '主要給付項目：給付項目給付金額行人或大眾交通工具意外傷害事故身故保險金保險金額╳1行人或大眾交通工具意外傷害事故第1級失能保險金保險金額╳1※'),
  ('cathay', '國泰人壽新行人或大眾交通工具意外傷害事故保險金附加條款', 2, '行人或大眾交通工具意外傷害事故第1級失能', '行人或大眾交通工具意外傷害事故第1級失能保險金', '保額 × 1', '主要給付項目：給付項目給付金額行人或大眾交通工具意外傷害事故身故保險金保險金額╳1行人或大眾交通工具意外傷害事故第1級失能保險金保險金額╳1※'),
  ('cathay', '國泰人壽新駕乘汽車意外傷害事故保險金附加條款', 1, '駕乘汽車意外傷害事故身故', '駕乘汽車意外傷害事故身故保險金', NULL, '第三條駕乘汽車意外傷害事故身故保險金或喪葬費用保險金的給付被保險人於本附加條款有效期間內遭受本附加條款第二條約定的駕乘汽車意外傷害事故，自該駕乘汽車意外傷害事故發生之日起一百八十日以內身故，本公司按照本契約保險單上所記載之保險金額給付「駕乘汽車意外傷害事故身故保險金」。'),
  ('cathay', '國泰人壽新駕乘汽車意外傷害事故保險金附加條款', 2, '駕乘汽車意外傷害事故第一級失能', '駕乘汽車意外傷害事故第一級失能保險金', NULL, '第四條駕乘汽車意外傷害事故第一級失能保險金的給付被保險人於本附加條款有效期間內，因遭受本附加條款第二條約定的駕乘汽車意外傷害事故，自該駕乘汽車意外傷害事故發生之日起一百八十日以內經診斷確定致成本契約附表所列失能等級第一級的項目之一，本公司按照本契約保險單上所記載之保險金額給付「駕乘汽車意外傷害事故第一級失能保險金」。'),
  ('cathay', '國泰人壽新騎乘機車或自行車意外傷害事故保險金附加條款', 1, '騎乘機車或自行車意外傷害事故身故', '騎乘機車或自行車意外傷害事故身故保險金', '保額 × 1', '主要給付項目：給付項目給付金額騎乘機車或自行車意外傷害事故身故保險金保險金額╳1騎乘機車或自行車意外傷害事故第1級失能保險金保險金額╳1※'),
  ('cathay', '國泰人壽新騎乘機車或自行車意外傷害事故保險金附加條款', 2, '騎乘機車或自行車意外傷害事故第1級失能', '騎乘機車或自行車意外傷害事故第1級失能保險金', '保額 × 1', '主要給付項目：給付項目給付金額騎乘機車或自行車意外傷害事故身故保險金保險金額╳1騎乘機車或自行車意外傷害事故第1級失能保險金保險金額╳1※');
